-- ====================================================================
-- Supabase PostgreSQL Schema & Work Plan Seed Data (RM-Retail POS V2.0)
-- Architecture: Vercel Serverless + Supabase (PostgreSQL)
-- Generated from: Project Detail Work Plan RM-Retail POS V2.0_20261015.xlsx
-- ====================================================================

-- 1. Create Projects Table
CREATE TABLE IF NOT EXISTS public.projects (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(255) NOT NULL,
  description TEXT DEFAULT NULL,
  assignee VARCHAR(255) DEFAULT NULL,
  status VARCHAR(50) DEFAULT 'Active',
  wbs VARCHAR(50) DEFAULT '0',
  percent_complete NUMERIC(5,2) DEFAULT 0.00,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- 2. Create Stages Table (Milestones)
CREATE TABLE IF NOT EXISTS public.stages (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  project_id BIGINT NOT NULL REFERENCES public.projects (id) ON DELETE CASCADE,
  wbs VARCHAR(50) DEFAULT NULL,
  title VARCHAR(255) NOT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  color VARCHAR(7) DEFAULT '#7b879a',
  sort_order INT DEFAULT 0,
  assignee VARCHAR(255) DEFAULT NULL,
  duration VARCHAR(50) DEFAULT NULL,
  weight_pct INT DEFAULT 0,
  percent_complete NUMERIC(5,2) DEFAULT 0.00,
  percent_work_complete NUMERIC(5,2) DEFAULT 0.00,
  status VARCHAR(50) DEFAULT 'Not Started',
  stuck_reason TEXT DEFAULT NULL,
  is_completed SMALLINT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- 3. Create Tasks Table (WBS Level 2, 3, 4)
CREATE TABLE IF NOT EXISTS public.tasks (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  stage_id BIGINT NOT NULL REFERENCES public.stages (id) ON DELETE CASCADE,
  wbs VARCHAR(50) DEFAULT NULL,
  title VARCHAR(255) NOT NULL,
  level INT DEFAULT 2,
  parent_wbs VARCHAR(50) DEFAULT NULL,
  start_date DATE NOT NULL,
  end_date DATE NOT NULL,
  duration VARCHAR(50) DEFAULT NULL,
  color VARCHAR(7) DEFAULT '#9fc7ff',
  lane INT DEFAULT 1,
  assignee VARCHAR(255) DEFAULT NULL,
  sort_order INT DEFAULT 0,
  percent_complete NUMERIC(5,2) DEFAULT 0.00,
  percent_work_complete NUMERIC(5,2) DEFAULT 0.00,
  status VARCHAR(50) DEFAULT 'Not Started',
  actual_start DATE DEFAULT NULL,
  actual_finish DATE DEFAULT NULL,
  stuck_reason TEXT DEFAULT NULL,
  remark TEXT DEFAULT NULL,
  is_completed SMALLINT DEFAULT 0,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP,
  updated_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- 4. Create Assignees Table
CREATE TABLE IF NOT EXISTS public.assignees (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(255) NOT NULL UNIQUE,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- 5. Create Colors Table
CREATE TABLE IF NOT EXISTS public.colors (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  color_code VARCHAR(7) NOT NULL UNIQUE,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- 6. Create Users Table (Supports local admin & Google OAuth account mapping)
CREATE TABLE IF NOT EXISTS public.users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  username VARCHAR(100) NOT NULL UNIQUE,
  password VARCHAR(255) DEFAULT NULL,
  display_name VARCHAR(150) NOT NULL,
  email VARCHAR(255) DEFAULT NULL UNIQUE,
  google_id VARCHAR(255) DEFAULT NULL,
  avatar_url TEXT DEFAULT NULL,
  created_at TIMESTAMPTZ DEFAULT CURRENT_TIMESTAMP
);

-- Indexes for high-performance querying
CREATE INDEX IF NOT EXISTS idx_stages_project_id ON public.stages(project_id);
CREATE INDEX IF NOT EXISTS idx_tasks_stage_id ON public.tasks(stage_id);
CREATE INDEX IF NOT EXISTS idx_stages_sort ON public.stages(sort_order, start_date);
CREATE INDEX IF NOT EXISTS idx_tasks_sort ON public.tasks(sort_order, start_date);
CREATE INDEX IF NOT EXISTS idx_tasks_wbs ON public.tasks(wbs);
CREATE INDEX IF NOT EXISTS idx_tasks_status ON public.tasks(status);

-- ====================================================================
-- Row Level Security (RLS) Configuration
-- ====================================================================
ALTER TABLE public.projects ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.stages ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.tasks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.assignees ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.colors ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Public can read projects" ON public.projects;
CREATE POLICY "Public can read projects" ON public.projects FOR SELECT USING (true);
DROP POLICY IF EXISTS "Public can read stages" ON public.stages;
CREATE POLICY "Public can read stages" ON public.stages FOR SELECT USING (true);
DROP POLICY IF EXISTS "Public can read tasks" ON public.tasks;
CREATE POLICY "Public can read tasks" ON public.tasks FOR SELECT USING (true);
DROP POLICY IF EXISTS "Public can read assignees" ON public.assignees;
CREATE POLICY "Public can read assignees" ON public.assignees FOR SELECT USING (true);
DROP POLICY IF EXISTS "Public can read colors" ON public.colors;
CREATE POLICY "Public can read colors" ON public.colors FOR SELECT USING (true);
DROP POLICY IF EXISTS "Enable all access for service role on projects" ON public.projects;
CREATE POLICY "Enable all access for service role on projects" ON public.projects FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Enable all access for service role on stages" ON public.stages;
CREATE POLICY "Enable all access for service role on stages" ON public.stages FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Enable all access for service role on tasks" ON public.tasks;
CREATE POLICY "Enable all access for service role on tasks" ON public.tasks FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Enable all access for service role on assignees" ON public.assignees;
CREATE POLICY "Enable all access for service role on assignees" ON public.assignees FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Enable all access for service role on colors" ON public.colors;
CREATE POLICY "Enable all access for service role on colors" ON public.colors FOR ALL USING (true) WITH CHECK (true);
DROP POLICY IF EXISTS "Enable all access for service role on users" ON public.users;
CREATE POLICY "Enable all access for service role on users" ON public.users FOR ALL USING (true) WITH CHECK (true);

-- ====================================================================
-- Wipe Old Data and Seed New Work Plan (RM-Retail POS V2.0)
-- ====================================================================
TRUNCATE TABLE public.tasks, public.stages, public.projects, public.assignees, public.colors RESTART IDENTITY CASCADE;

